// HTTP client configuration
esp_http_client_config_t http_config = {
  .url = "http://api.openweathermap.org/data/2.5/weather",
  .event_handler = _http_event_handler,
  .buffer_size = 2048,
  .buffer_size_tcp = 2048,
};

esp_http_client_handle_t http_client = esp_http_client_init(&http_config);

// Set query parameters
esp_http_client_set_method(http_client, HTTP_METHOD_GET);
esp_http_client_set_header(http_client, "Content-Type", "application/json");

// Execute request
esp_http_client_perform(http_client);
int response_code = esp_http_client_get_response_code(http_client);

if (response_code == 200) {
  int content_length = esp_http_client_get_content_length(http_client);
  char* response_buffer = malloc(content_length + 1);
  int read_bytes = esp_http_client_read(http_client, response_buffer, content_length);
  response_buffer[read_bytes] = '\0';
  // Parse JSON using cjson
  cJSON* json = cJSON_Parse(response_buffer);
  // Extract temperature
  cJSON* main = cJSON_GetObjectItem(json, "main");
  cJSON* temp = cJSON_GetObjectItem(main, "temp");
  float temperature = temp->valuedouble;
  free(response_buffer);
}

esp_http_client_cleanup(http_client);

