// Download and display satellite image
void downloadSatelliteImage(const char* imageUrl) {
  HTTPClient http;
  http.begin(imageUrl);
  int contentType = http.getHeader("Content-Type");

  if (http.GET() > 0) {
    // Check if response is image
    if (contentType == 0 || String(contentType).indexOf("image/jpeg") >= 0) {
      // Get image data
      size_t len = http.getSize();
      uint8_t* imgData = (uint8_t*)ps_malloc(len);

      WiFiClient* stream = http.getStreamPtr();
      size_t offset = 0;
      while (http.connected() && offset < len) {
        size_t toRead = stream->available();
        size_t bytesRead = stream->read(imgData + offset, toRead);
        offset += bytesRead;
      }

      // Display image using Arduino_GFX
      gfx->drawJpg(imgData, offset, 0, 0);
      free(imgData);
    }
  }
  http.end();
}

