// Store WiFi credentials in NVS
void saveWifiCredentials(const char* ssid, const char* password) {
  nvs_open("storage", NVS_READWRITE, &handle);
  nvs_set_str(handle, "ssid", ssid);
  nvs_set_str(handle, "password", password);
  nvs_commit(handle);
  nvs_close(handle);
}

// Retrieve WiFi credentials
void loadWifiCredentials() {
  nvs_open("storage", NVS_READONLY, &handle);
  char ssid[32];
  char password[64];
  size_t ssid_len = sizeof(ssid);
  size_t password_len = sizeof(password);
  nvs_get_str(handle, "ssid", ssid, &ssid_len);
  nvs_get_str(handle, "password", password, &password_len);
  // Use credentials
  WiFi.begin(ssid, password);
  nvs_close(handle);
}

